package com.npchealthregen;

final class RecoveryCalculator
{
	static final class Range
	{
		private final int minimum;
		private final int maximum;

		Range(int minimum, int maximum)
		{
			this.minimum = minimum;
			this.maximum = maximum;
		}

		int getMinimum()
		{
			return minimum;
		}

		int getMaximum()
		{
			return maximum;
		}
	}

	static final class TickWindow
	{
		private final long earliest;
		private final long latest;

		TickWindow(long earliest, long latest)
		{
			this.earliest = earliest;
			this.latest = latest;
		}

		long getEarliest()
		{
			return earliest;
		}

		long getLatest()
		{
			return latest;
		}
	}

	private RecoveryCalculator()
	{
	}

	static Range healthFromRatio(int ratio, int scale, int maximumHitpoints)
	{
		if (ratio < 0 || scale <= 0 || maximumHitpoints <= 0)
		{
			return null;
		}
		if (ratio == 0)
		{
			return new Range(0, 0);
		}

		int minimum = 1;
		int maximum = maximumHitpoints;
		if (scale > 1)
		{
			if (ratio > 1)
			{
				minimum = (maximumHitpoints * (ratio - 1) + scale - 2) / (scale - 1);
			}
			maximum = (maximumHitpoints * ratio - 1) / (scale - 1);
			maximum = Math.min(maximum, maximumHitpoints);
		}

		return new Range(Math.min(minimum, maximumHitpoints), Math.max(minimum, maximum));
	}

	static TickWindow timeUntilFull(
		Range currentHitpoints,
		int maximumHitpoints,
		long sampleTick,
		long now,
		int regenInterval,
		RegenTimer timer)
	{
		if (currentHitpoints == null || maximumHitpoints <= 0 || sampleTick < 0 || regenInterval <= 0)
		{
			return null;
		}

		int minimumMissing = Math.max(0, maximumHitpoints - currentHitpoints.getMaximum());
		int maximumMissing = Math.max(0, maximumHitpoints - currentHitpoints.getMinimum());
		if (maximumMissing == 0)
		{
			return new TickWindow(0, 0);
		}

		long referenceTick = sampleTick + 1;
		RegenTimer.Window next = timer.getUpcomingWindow(referenceTick, regenInterval);
		if (next == null)
		{
			return null;
		}

		long earliestAbsolute = minimumMissing == 0
			? now
			: referenceTick + next.getEarliestTicks() + (long) (minimumMissing - 1) * regenInterval;
		long latestAbsolute = referenceTick + next.getLatestTicks()
			+ (long) (maximumMissing - 1) * regenInterval;
		return new TickWindow(
			Math.max(0, earliestAbsolute - now),
			Math.max(0, latestAbsolute - now));
	}

	static Range projectHealth(
		Range observed,
		int maximumHitpoints,
		long sampleTick,
		long now,
		int regenInterval,
		RegenTimer timer)
	{
		if (observed == null || maximumHitpoints <= 0 || sampleTick < 0
			|| now <= sampleTick || regenInterval <= 0)
		{
			return observed;
		}

		long referenceTick = sampleTick + 1;
		RegenTimer.Window next = timer.getUpcomingWindow(referenceTick, regenInterval);
		if (next == null)
		{
			return observed;
		}

		long earliestFirst = referenceTick + next.getEarliestTicks();
		long latestFirst = referenceTick + next.getLatestTicks();
		long guaranteedHeals = completedCycles(now, latestFirst, regenInterval);
		long possibleHeals = completedCycles(now, earliestFirst, regenInterval);
		return new Range(
			(int) Math.min(maximumHitpoints, observed.getMinimum() + guaranteedHeals),
			(int) Math.min(maximumHitpoints, observed.getMaximum() + possibleHeals));
	}

	static Range defenceAtFull(
		int currentDefence,
		int baseDefence,
		Range currentHitpoints,
		int maximumHitpoints)
	{
		if (currentDefence < 0 || baseDefence <= 0 || currentHitpoints == null || maximumHitpoints <= 0)
		{
			return null;
		}

		int minimumMissing = Math.max(0, maximumHitpoints - currentHitpoints.getMaximum());
		int maximumMissing = Math.max(0, maximumHitpoints - currentHitpoints.getMinimum());
		return new Range(
			Math.min(baseDefence, currentDefence + minimumMissing),
			Math.min(baseDefence, currentDefence + maximumMissing));
	}

	private static long completedCycles(long now, long firstTick, int interval)
	{
		return now < firstTick ? 0 : 1 + (now - firstTick) / interval;
	}
}

package com.npchealthregen;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class NpcHealthRegenOverlay extends OverlayPanel
{
	private static final Color WARNING = new Color(255, 170, 0);
	private static final Color WINDOW_NOW = new Color(255, 80, 80);
	private static final Color LEARNED = new Color(80, 220, 120);

	private final NpcHealthRegenPlugin plugin;
	private final NpcHealthRegenConfig config;

	@Inject
	private NpcHealthRegenOverlay(NpcHealthRegenPlugin plugin, NpcHealthRegenConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		// Default priority: panels from other plugins in this corner keep their order.
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.getTargetName() == null)
		{
			return null;
		}

		RegenTimer timer = plugin.getTimer();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("NPC Health Regen")
			.build());

		if (config.showNpcName())
		{
			addLine("Target", plugin.getTargetName(), Color.WHITE);
		}
		if (plugin.isTargetOutOfView())
		{
			addLine("Target", "Out of view (timer kept)", WARNING);
		}
		addVenomChanceLine();
		addVenomLines();
		String partySource = plugin.getPartySourceName();
		if (config.showPartySource() && partySource != null)
		{
			addLine("Timer from", partySource, LEARNED);
		}
		if (config.showTickCounter())
		{
			addLine("Game tick", Long.toString(plugin.getTick()), Color.WHITE);
		}
		if (config.showObservationSource())
		{
			addLine("Observation", plugin.getObservationSourceLabel(), Color.WHITE);
		}
		if (config.showInspectedStats() && plugin.getLastInspectedHitpoints() >= 0)
		{
			addLine("Inspected HP", Integer.toString(plugin.getLastInspectedHitpoints()), Color.WHITE);
			if (plugin.getLastInspectedDefence() >= 0)
			{
				addLine("Inspected Defence", Integer.toString(plugin.getLastInspectedDefence()), Color.WHITE);
			}
		}
		if (config.showBaseStats())
		{
			if (plugin.getMaximumHitpoints() > 0)
			{
				addLine("Maximum HP", Integer.toString(plugin.getMaximumHitpoints()), Color.WHITE);
			}
			if (plugin.getBaseDefence() > 0)
			{
				addLine("Highest inspected Defence",
					Integer.toString(plugin.getBaseDefence()), Color.WHITE);
			}
		}

		RecoveryCalculator.Range currentHitpoints = plugin.getCurrentHitpoints();
		if (config.showCurrentHealth() && currentHitpoints != null)
		{
			String estimate = plugin.isCurrentHitpointsExact() ? "" : "~";
			addLine("Current HP", estimate + formatRange(currentHitpoints), Color.WHITE);
		}
		if (config.showDefenceAtFullHp())
		{
			RecoveryCalculator.Range defence = plugin.getDefenceAtFullHitpoints();
			if (defence != null)
			{
				addLine("Defence at full HP", "~" + formatRange(defence), Color.WHITE);
			}
		}
		if (config.showRegenRate())
		{
			String source = plugin.isLearnedRegen() ? " (learned)" : " (default)";
			addLine("Regen rate", formatRate(plugin.getActiveRegenTicks()) + source,
				plugin.isLearnedRegen() ? LEARNED : Color.WHITE);
		}

		if (timer.getState() == RegenTimer.State.WAITING_FOR_RESPAWN)
		{
			addRespawnCountdown(timer);
		}
		if (config.showRespawnTime())
		{
			addRespawnRate(timer);
		}

		RegenTimer.Window window = timer.getUpcomingWindow(
			plugin.getTick(), plugin.getActiveRegenTicks());
		if (window == null)
		{
			if (config.showTimeUntilFullHp() && currentHitpoints != null
				&& plugin.getMaximumHitpoints() > 0)
			{
				boolean full = currentHitpoints.getMinimum() >= plugin.getMaximumHitpoints();
				addLine("Full HP in", full ? "0.0s" : "Need first heal",
					full ? LEARNED : WARNING);
			}
			String status = timer.getState() == RegenTimer.State.WAITING_FOR_RESPAWN
				? "Waiting for respawn"
				: plugin.isInspectionPending()
					? "Waiting for Inspect/Examine result"
				: plugin.isUsingMonsterInspection()
					? "Cast Inspect/Examine again"
					: "Keep splashing to find regen";
			addLine("Status", status, Color.WHITE);
			return super.render(graphics);
		}

		long earliest = window.getEarliestTicks();
		long latest = window.getLatestTicks();
		Color colour = earliest == 0 ? WINDOW_NOW
			: earliest <= config.warningTicks() ? WARNING : Color.WHITE;
		String label = earliest == 0 ? "Regen window" : "Next regen";
		String value = earliest == 0
			? (latest == 0 ? "NOW" : "NOW - " + formatTicks(latest))
			: formatWindow(earliest, latest);
		addLine(label, "~" + value, colour);

		if (config.showTimeUntilFullHp())
		{
			RecoveryCalculator.TickWindow fullHp = plugin.getTimeUntilFullHitpoints();
			if (fullHp != null)
			{
				String estimate = fullHp.getLatest() == 0 ? "" : "~";
				addLine("Full HP in", estimate + formatDurationWindow(fullHp),
					fullHp.getEarliest() == 0 ? LEARNED : Color.WHITE);
			}
		}

		return super.render(graphics);
	}

	/** Your chance to envenom the NPC with the venom weapon and serpentine helm you are wearing. */
	private void addVenomChanceLine()
	{
		VenomChance.Setup setup = plugin.getVenomSetup();
		if (!config.showVenomChance() || setup == null)
		{
			return;
		}

		addLine("Venom chance", setup.describe(), setup.isGuaranteed() ? LEARNED : WARNING);
	}

	private void addVenomLines()
	{
		VenomRing ring = plugin.getVenomRing();
		if (!config.showVenomRing() || ring.getStatus() == VenomRing.Status.NONE)
		{
			return;
		}

		long now = plugin.getTick();
		switch (ring.getStatus())
		{
			case PROCCED:
				addLine("Venom", "Procced after " + ring.getLastObservedDelay() + "t", LEARNED);
				return;
			case NO_VENOM:
				addLine("Venom", "No venom", WINDOW_NOW);
				return;
			default:
				break;
		}

		long earliest = Math.max(0, ring.getProcEarliest() - now);
		long latest = Math.max(0, ring.getProcLatest() - now);
		addLine("Venom procs in", earliest == latest ? formatTicks(earliest) : formatWindow(earliest, latest),
			Color.WHITE);
		NpcHealthRegenSceneOverlay.RingState state = NpcHealthRegenSceneOverlay.ringState(
			ring, now, plugin.getDynamiteDelayTicks());
		addLine("Dynamite", state.label, state.colour);
	}

	private void addRespawnCountdown(RegenTimer timer)
	{
		long remaining = timer.getRespawnTicksRemaining(plugin.getTick());
		if (remaining >= 0)
		{
			addLine("Respawn in", formatTicks(remaining), remaining == 0 ? WINDOW_NOW : WARNING);
		}
		else
		{
			addLine("Dead for", formatTicks(timer.getRespawnTicksElapsed(plugin.getTick())), WARNING);
		}
	}

	private void addRespawnRate(RegenTimer timer)
	{
		if (plugin.getActiveRespawnTicks() > 0)
		{
			String source = plugin.isLearnedRespawn() ? " (learned)" : " (default)";
			addLine("Respawn rate", formatRate(plugin.getActiveRespawnTicks()) + source,
				plugin.isLearnedRespawn() ? LEARNED : Color.WHITE);
		}
		else if (timer.getState() != RegenTimer.State.WAITING_FOR_RESPAWN)
		{
			addLine("Respawn rate", "Not learned yet", Color.WHITE);
		}
	}

	private void addLine(String left, String right, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.rightColor(rightColor)
			.build());
	}

	private String formatWindow(long earliest, long latest)
	{
		if (earliest == latest)
		{
			return formatTicks(earliest);
		}

		String ticks = earliest + "-" + latest + " ticks";
		if (!config.showSeconds())
		{
			return ticks;
		}
		return ticks + " (" + formatSeconds(earliest) + "-" + formatSeconds(latest) + "s)";
	}

	private String formatTicks(long ticks)
	{
		String value = ticks + (ticks == 1 ? " tick" : " ticks");
		return config.showSeconds() ? value + " (" + formatSeconds(ticks) + "s)" : value;
	}

	private String formatRate(int ticks)
	{
		return config.showSeconds()
			? ticks + "t / " + formatSeconds(ticks) + "s"
			: ticks + " ticks";
	}

	private static String formatRange(RecoveryCalculator.Range range)
	{
		return range.getMinimum() == range.getMaximum()
			? Integer.toString(range.getMinimum())
			: range.getMinimum() + "-" + range.getMaximum();
	}

	private static String formatDurationWindow(RecoveryCalculator.TickWindow window)
	{
		if (window.getEarliest() == window.getLatest())
		{
			return formatDuration(window.getEarliest());
		}
		return formatDuration(window.getEarliest()) + "-" + formatDuration(window.getLatest());
	}

	private static String formatDuration(long ticks)
	{
		long tenths = Math.max(0, ticks) * 6L;
		long minutes = tenths / 600L;
		long seconds = (tenths % 600L) / 10L;
		long decimal = tenths % 10L;
		return minutes > 0
			? String.format(Locale.ENGLISH, "%dm %d.%ds", minutes, seconds, decimal)
			: String.format(Locale.ENGLISH, "%d.%ds", seconds, decimal);
	}

	private static String formatSeconds(long ticks)
	{
		return String.format(Locale.ENGLISH, "%.1f", ticks * 0.6d);
	}
}

package com.npchealthregen;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

final class MonsterInspectionReader
{
	private static final Pattern BREAK_TAG = Pattern.compile("(?i)<br\\s*/?>");
	private static final Pattern HTML_TAG = Pattern.compile("<[^>]*>");
	// The whitespace after the colon may span a line break, so a label and its
	// value can be held in separate widgets.
	private static final Pattern HITPOINTS = Pattern.compile("(?im)^[ \\t]*Hitpoints[ \\t]*:\\s*([0-9][0-9,]*)[ \\t]*$");
	private static final Pattern DEFENCE = Pattern.compile("(?im)^[ \\t]*Defence[ \\t]*:\\s*([0-9][0-9,]*)[ \\t]*$");
	private static final Pattern COMBAT_LEVEL_SUFFIX = Pattern.compile("(?i)\\s*\\(level-\\d+\\)$");
	private static final Pattern ELLIPSIS = Pattern.compile("(\\.\\.\\.|…)$");
	private static final int MIN_TRUNCATED_NAME_LENGTH = 3;

	static final class Snapshot
	{
		private final int hitpoints;
		private final int defence;

		private Snapshot(int hitpoints, int defence)
		{
			this.hitpoints = hitpoints;
			this.defence = defence;
		}

		int getHitpoints()
		{
			return hitpoints;
		}

		int getDefence()
		{
			return defence;
		}
	}

	private MonsterInspectionReader()
	{
	}

	static Snapshot find(Client client, String targetName)
	{
		if (targetName == null)
		{
			return null;
		}

		// The Monster Examine/Inspect result panel. Read it directly so the
		// result does not depend on where the panel is nested in the layout.
		Widget name = client.getWidget(InterfaceID.DreamMonsterStat.MONSTER_NAME);
		Widget stats = client.getWidget(InterfaceID.DreamMonsterStat.MONSTER_STATS);
		if (name != null && stats != null && !name.isHidden() && !stats.isHidden())
		{
			List<String> panelText = new ArrayList<>(collectVisibleText(name));
			panelText.addAll(collectVisibleText(stats));
			Snapshot snapshot = parse(targetName, panelText);
			if (snapshot != null)
			{
				return snapshot;
			}
		}

		Widget[] roots = client.getWidgetRoots();
		if (roots == null)
		{
			return null;
		}

		for (Widget root : roots)
		{
			Snapshot snapshot = parse(targetName, collectVisibleText(root));
			if (snapshot != null)
			{
				return snapshot;
			}
		}
		return null;
	}

	static Snapshot parse(String targetName, Iterable<String> widgetText)
	{
		String expectedName = normalise(targetName);
		boolean nameFound = false;
		StringBuilder combined = new StringBuilder();

		for (String rawText : widgetText)
		{
			String text = normalise(rawText);
			for (String line : text.split("\\R"))
			{
				if (namesMatch(line, expectedName))
				{
					nameFound = true;
				}
			}
			combined.append(text).append('\n');
		}

		int hitpoints = readStat(HITPOINTS, combined);
		int defence = readStat(DEFENCE, combined);
		return nameFound && hitpoints >= 0 ? new Snapshot(hitpoints, defence) : null;
	}

	/**
	 * The panel title is cut to fit the side panel ("Deranged archaeologi...")
	 * and may carry a combat level suffix.
	 */
	static boolean namesMatch(String panelLine, String expectedName)
	{
		String line = stripLevel(panelLine);
		String expected = stripLevel(expectedName);
		if (expected.isEmpty())
		{
			return false;
		}
		if (line.equals(expected))
		{
			return true;
		}

		Matcher ellipsis = ELLIPSIS.matcher(line);
		if (!ellipsis.find())
		{
			return false;
		}
		String prefix = line.substring(0, ellipsis.start()).trim();
		return prefix.length() >= Math.min(MIN_TRUNCATED_NAME_LENGTH, expected.length())
			&& expected.startsWith(prefix);
	}

	private static String stripLevel(String name)
	{
		return COMBAT_LEVEL_SUFFIX.matcher(name.trim()).replaceAll("").trim().toLowerCase(Locale.ENGLISH);
	}

	private static List<String> collectVisibleText(Widget root)
	{
		if (root == null)
		{
			return Collections.emptyList();
		}

		List<String> text = new ArrayList<>();
		Deque<Widget> pending = new ArrayDeque<>();
		Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		pending.push(root);

		while (!pending.isEmpty())
		{
			Widget widget = pending.pop();
			if (!visited.add(widget) || widget.isHidden())
			{
				continue;
			}

			String widgetText = widget.getText();
			if (widgetText != null && !widgetText.isEmpty())
			{
				text.add(widgetText);
			}

			// Pushed last-first so the stack yields children top-down, keeping a
			// label ahead of a value held in a following widget.
			addChildren(pending, widget.getNestedChildren());
			addChildren(pending, widget.getDynamicChildren());
			addChildren(pending, widget.getStaticChildren());
		}
		return text;
	}

	private static void addChildren(Deque<Widget> pending, Widget[] children)
	{
		if (children == null)
		{
			return;
		}

		for (int i = children.length - 1; i >= 0; i--)
		{
			if (children[i] != null)
			{
				pending.push(children[i]);
			}
		}
	}

	private static int readStat(Pattern pattern, CharSequence text)
	{
		Matcher matcher = pattern.matcher(text);
		if (!matcher.find())
		{
			return -1;
		}

		try
		{
			return Integer.parseInt(matcher.group(1).replace(",", ""));
		}
		catch (NumberFormatException ignored)
		{
			return -1;
		}
	}

	private static String normalise(String text)
	{
		if (text == null)
		{
			return "";
		}
		return HTML_TAG.matcher(BREAK_TAG.matcher(text).replaceAll("\n"))
			.replaceAll("")
			.replace("&nbsp;", " ")
			.replace(' ', ' ')
			.trim();
	}
}

package com.npchealthregen;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

final class NpcHealthRegenSceneOverlay extends Overlay
{
	private static final Color WARNING = new Color(255, 170, 0);
	private static final Color VENOM_GREEN = new Color(60, 200, 90);
	private static final Color LATE_RED = new Color(230, 60, 60);
	private static final int RING_DIAMETER = 24;
	// Model units above the NPC's head where the overhead text is anchored, as plugins usually do.
	private static final int OVERHEAD_HEIGHT = 40;
	private static final Color RESPAWN_FILL = new Color(255, 170, 0, 35);
	private static final Color TEXT = Color.WHITE;

	private final Client client;
	private final NpcHealthRegenPlugin plugin;
	private final NpcHealthRegenConfig config;

	@Inject
	private NpcHealthRegenSceneOverlay(
		Client client,
		NpcHealthRegenPlugin plugin,
		NpcHealthRegenConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		NPC target = plugin.getTarget();
		if (target != null)
		{
			renderTarget(graphics, target);
		}
		else if (config.showRespawnTile()
			&& plugin.getTimer().getState() == RegenTimer.State.WAITING_FOR_RESPAWN)
		{
			renderRespawnTile(graphics);
		}
		return null;
	}

	private void renderTarget(Graphics2D graphics, NPC target)
	{
		Shape highlight = highlightShape(target, config.npcHighlight());
		if (highlight != null)
		{
			Color border = config.highlightColour();
			Color fill = new Color(border.getRed(), border.getGreen(), border.getBlue(),
				border.getAlpha() * 35 / 255);
			renderShape(graphics, highlight, border, fill);
		}

		renderOverhead(graphics, target);
	}

	/**
	 * The regen countdown, and above it the venom label and ring, stacked in pixels from one anchor
	 * so they cannot overlap each other. Beside the NPC (see OverheadLayout) they also stay clear of
	 * other plugins that draw above its head.
	 */
	private void renderOverhead(Graphics2D graphics, NPC target)
	{
		String regenText = null;
		Color regenColour = TEXT;
		if (config.showOverheadRegenCountdown())
		{
			RegenTimer.Window window = plugin.getTimer().getUpcomingWindow(
				plugin.getTick(), plugin.getActiveRegenTicks());
			if (window != null)
			{
				regenText = formatRegenCountdown(window);
				regenColour = window.getEarliestTicks() <= config.warningTicks() ? WARNING : TEXT;
			}
		}

		VenomRing ring = plugin.getVenomRing();
		RingState venom = config.showVenomRing() && ring.getStatus() != VenomRing.Status.NONE
			? ringState(ring, plugin.getTick(), plugin.getDynamiteDelayTicks()) : null;
		if (regenText == null && venom == null)
		{
			return;
		}

		Point anchor = target.getCanvasTextLocation(
			graphics, "", target.getLogicalHeight() + OVERHEAD_HEIGHT);
		if (anchor == null)
		{
			return;
		}

		FontMetrics metrics = graphics.getFontMetrics();
		OverheadLayout.Layout layout = OverheadLayout.layout(anchor.getX(), anchor.getY(),
			plugin.getOverheadPlacement(), config.overheadSideOffset(),
			metrics.getAscent(), metrics.getDescent(),
			regenText == null ? 0 : metrics.stringWidth(regenText),
			venom == null ? 0 : RING_DIAMETER,
			venom == null ? 0 : metrics.stringWidth(venom.label));

		if (regenText != null)
		{
			OverlayUtil.renderTextLocation(graphics,
				new Point(layout.regenX, layout.regenBaselineY), regenText, regenColour);
		}
		if (venom != null)
		{
			ProgressPieComponent pie = new ProgressPieComponent();
			pie.setPosition(new Point(layout.ringCentreX, layout.ringCentreY));
			pie.setDiameter(RING_DIAMETER);
			pie.setProgress(venom.progress);
			pie.setBorderColor(venom.colour);
			pie.setFill(new Color(venom.colour.getRed(), venom.colour.getGreen(), venom.colour.getBlue(), 110));
			pie.render(graphics);
			OverlayUtil.renderTextLocation(graphics,
				new Point(layout.labelX, layout.labelBaselineY), venom.label, venom.colour);
		}
	}

	static final class RingState
	{
		final double progress;
		final Color colour;
		final String label;

		RingState(double progress, Color colour, String label)
		{
			this.progress = progress;
			this.colour = colour;
			this.label = label;
		}
	}

	/** What the venom ring shows: wait, send the dynamite, too late, or the result. */
	static RingState ringState(VenomRing ring, long now, int dynamiteDelayTicks)
	{
		switch (ring.getStatus())
		{
			case PROCCED:
				return new RingState(1, VENOM_GREEN, "Venom!");
			case NO_VENOM:
				return new RingState(1, LATE_RED, "No venom");
			default:
				break;
		}

		double progress = ring.getProgress(now);
		long[] window = ring.getDynamiteWindow(dynamiteDelayTicks);
		if (window == null || window[1] < window[0])
		{
			return new RingState(progress, LATE_RED, "No window");
		}
		if (now < window[0])
		{
			return new RingState(progress, WARNING, "Wait " + (window[0] - now) + "t");
		}
		if (now <= window[1])
		{
			return new RingState(progress, VENOM_GREEN, "Send " + (window[1] - now) + "t");
		}
		return new RingState(progress, LATE_RED, "Too late");
	}

	private Shape highlightShape(NPC target, NpcHealthRegenConfig.NpcHighlight style)
	{
		switch (style)
		{
			case TILE:
				// Follows the model smoothly as it walks, covering its full size.
				return target.getCanvasTilePoly();
			case TRUE_TILE:
			{
				int size = target.getTransformedComposition() == null
					? 1 : target.getTransformedComposition().getSize();
				return tileArea(target.getWorldLocation(), size);
			}
			case HULL:
				return target.getConvexHull();
			default:
				return null;
		}
	}

	/** The on-screen area of a size x size NPC whose south-west tile is worldPoint. */
	private Polygon tileArea(WorldPoint worldPoint, int size)
	{
		if (worldPoint == null)
		{
			return null;
		}

		LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
		if (localPoint == null)
		{
			return null;
		}

		LocalPoint centre = areaCentre(localPoint, size);
		return Perspective.getCanvasTileAreaPoly(client, centre, Math.max(1, size));
	}

	private static LocalPoint areaCentre(LocalPoint southWest, int size)
	{
		int offset = Perspective.LOCAL_TILE_SIZE * (Math.max(1, size) - 1) / 2;
		return southWest.plus(offset, offset);
	}

	private void renderRespawnTile(Graphics2D graphics)
	{
		WorldPoint worldPoint = plugin.getLastTargetPoint();
		if (worldPoint == null)
		{
			return;
		}

		LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
		if (localPoint == null)
		{
			return;
		}

		int size = Math.max(1, plugin.getLastTargetSize());
		LocalPoint centre = areaCentre(localPoint, size);
		Polygon polygon = Perspective.getCanvasTileAreaPoly(client, centre, size);
		renderShape(graphics, polygon, WARNING, RESPAWN_FILL);

		long remaining = plugin.getTimer().getRespawnTicksRemaining(plugin.getTick());
		String text = remaining >= 0
			? "Respawn: " + remaining + "t"
			: "Dead: " + plugin.getTimer().getRespawnTicksElapsed(plugin.getTick()) + "t";
		Point canvasPoint = Perspective.localToCanvas(client, centre, worldPoint.getPlane());
		if (canvasPoint == null)
		{
			return;
		}

		int textWidth = graphics.getFontMetrics().stringWidth(text);
		int textHeight = graphics.getFontMetrics().getAscent();
		OverlayUtil.renderTextLocation(graphics,
			new Point(canvasPoint.getX() - textWidth / 2, canvasPoint.getY() + textHeight / 2),
			text, TEXT);
	}

	static String formatRegenCountdown(RegenTimer.Window window)
	{
		long earliest = window.getEarliestTicks();
		long latest = window.getLatestTicks();
		if (earliest == 0)
		{
			return latest == 0 ? "Regen: ~NOW" : "Regen: ~NOW-" + latest + "t";
		}
		return earliest == latest
			? "Regen: ~" + earliest + "t"
			: "Regen: ~" + earliest + "-" + latest + "t";
	}

	private static void renderShape(
		Graphics2D graphics,
		Shape shape,
		Color border,
		Color fill)
	{
		if (shape == null)
		{
			return;
		}
		graphics.setStroke(new BasicStroke(2.0f));
		graphics.setColor(border);
		graphics.draw(shape);
		graphics.setColor(fill);
		graphics.fill(shape);
	}
}

package com.npchealthregen;

/**
 * How likely a landed hit is to envenom an NPC, from the worn weapon and serpentine helm.
 *
 * The figures are the OSRS Wiki's (Venom, Serpentine helm and each weapon's own page). Against
 * an NPC a charged serpentine helm makes the toxic blowpipe, trident of the swamp and toxic
 * staff of the dead envenom every landed hit. Without the helm they envenom 25% of landed hits,
 * and the noxious halberd envenoms 33% (50% with the helm).
 *
 * A hit by a player that passes its accuracy roll always deals at least 1 damage, while a failed
 * roll shows 0, so a hitsplat above 0 is a landed hit and the percentage here is the chance that
 * this hit envenoms. The wiki also gives the helm alone 1/6 with a non-poisoned melee weapon and
 * 1/2 with poisoned weapons; those are not modelled, as they depend on the attack style.
 */
final class VenomChance
{
	static final int GUARANTEED_PERCENT = 100;

	enum Weapon
	{
		TOXIC_BLOWPIPE("Toxic blowpipe", 25, 100),
		TRIDENT_OF_THE_SWAMP("Trident of the swamp", 25, 100),
		TOXIC_STAFF_OF_THE_DEAD("Toxic staff of the dead", 25, 100),
		NOXIOUS_HALBERD("Noxious halberd", 33, 50);

		private final String displayName;
		private final int percentWithoutHelm;
		private final int percentWithHelm;

		Weapon(String displayName, int percentWithoutHelm, int percentWithHelm)
		{
			this.displayName = displayName;
			this.percentWithoutHelm = percentWithoutHelm;
			this.percentWithHelm = percentWithHelm;
		}

		String getDisplayName()
		{
			return displayName;
		}
	}

	/** A worn venom weapon, and whether a charged serpentine helm is worn with it. */
	static final class Setup
	{
		private final Weapon weapon;
		private final boolean serpentineHelm;

		Setup(Weapon weapon, boolean serpentineHelm)
		{
			this.weapon = weapon;
			this.serpentineHelm = serpentineHelm;
		}

		Weapon getWeapon()
		{
			return weapon;
		}

		boolean hasSerpentineHelm()
		{
			return serpentineHelm;
		}

		/** @return the chance, in percent, that a landed hit envenoms an NPC */
		int getPercent()
		{
			return serpentineHelm ? weapon.percentWithHelm : weapon.percentWithoutHelm;
		}

		/** @return whether every landed hit envenoms, which is what the venom ring relies on */
		boolean isGuaranteed()
		{
			return getPercent() >= GUARANTEED_PERCENT;
		}

		/** @return the chance as shown to the player, noting a missing helm */
		String describe()
		{
			String percent = getPercent() + "%";
			return serpentineHelm || isGuaranteed() ? percent : percent + " (no helm)";
		}
	}

	private VenomChance()
	{
	}
}

package com.npchealthregen;

/**
 * Counts down from envenoming the selected NPC to its first venom damage, and
 * the window in which a poison dynamite must be sent to land on the NPC at
 * full health but before that damage.
 *
 * Poison and venom damage run on one timer per NPC that fires every 30 of the
 * NPC's active ticks. Envenoming switches the timer on without restarting it,
 * so the first hit lands (30 - ticks already counted) after the venom is
 * applied. That count is zero on an NPC that has never been poisoned, or one
 * killed by a poison or venom hit; after another killing blow it is the ticks
 * since the last poison hit before the death.
 */
final class VenomRing
{
	enum Status
	{
		NONE,
		COUNTING,
		PROCCED,
		NO_VENOM
	}

	static final int TIMER_TICKS = 30;
	private static final int RESULT_DISPLAY_TICKS = 5;
	// Allow the first venom hit a little late before calling it a failure.
	private static final int PROC_GRACE_TICKS = 2;

	private Status status = Status.NONE;
	private boolean shared;
	private long appliedTick = -1;
	private long procEarliest = -1;
	private long procLatest = -1;
	private long fullHpTick = -1;
	private long resolvedTick = -1;
	private long lastPoisonHitTick = -1;
	// Timer ticks already counted, carried into the NPC's next life.
	private int clockMin;
	private int clockMax;
	private int freshDelay = TIMER_TICKS;
	private int lastObservedDelay = -1;

	void reset()
	{
		status = Status.NONE;
		shared = false;
		lastPoisonHitTick = -1;
		clockMin = 0;
		clockMax = 0;
		lastObservedDelay = -1;
	}

	/** Uses a first-hit delay measured on an earlier NPC of the same type. */
	void setFreshDelay(int ticks)
	{
		freshDelay = ticks;
	}

	int getFreshDelay()
	{
		return freshDelay;
	}

	/** @return whether poison or venom is already ticking on the NPC */
	boolean isNpcPoisoned(long now)
	{
		return status == Status.COUNTING
			|| (lastPoisonHitTick >= 0 && now - lastPoisonHitTick <= TIMER_TICKS);
	}

	/**
	 * Starts the countdown for venom applied by this client's hit.
	 * @param fullHpTick the latest tick by which regen restores the hit's
	 * damage, or -1 if unknown
	 * @return false if the NPC was already poisoned or envenomed
	 */
	boolean start(long appliedTick, long fullHpTick)
	{
		if (isNpcPoisoned(appliedTick))
		{
			return false;
		}

		this.appliedTick = appliedTick;
		this.fullHpTick = fullHpTick;
		procEarliest = appliedTick + freshDelay - clockMax;
		procLatest = appliedTick + freshDelay - clockMin;
		status = Status.COUNTING;
		shared = false;
		return true;
	}

	/** Starts or refreshes the countdown from a party member's venom hit. */
	void startShared(long appliedTick, long procEarliest, long procLatest, long fullHpTick)
	{
		if (status == Status.COUNTING && !shared)
		{
			// This client's own hit is first-hand.
			return;
		}

		this.appliedTick = appliedTick;
		this.procEarliest = procEarliest;
		this.procLatest = procLatest;
		this.fullHpTick = fullHpTick;
		status = Status.COUNTING;
		shared = true;
	}

	void onPoisonHit(long tick, boolean venom)
	{
		if (status == Status.COUNTING && venom)
		{
			status = Status.PROCCED;
			resolvedTick = tick;
			lastObservedDelay = (int) (tick - appliedTick);
			if (!shared && clockMin == clockMax)
			{
				int delay = lastObservedDelay + clockMin;
				if (Math.abs(delay - TIMER_TICKS) <= 3)
				{
					freshDelay = delay;
				}
			}
		}
		lastPoisonHitTick = tick;
	}

	void onTick(long now)
	{
		if (status == Status.COUNTING && now > procLatest + PROC_GRACE_TICKS)
		{
			status = Status.NO_VENOM;
			resolvedTick = now;
		}
		else if ((status == Status.PROCCED || status == Status.NO_VENOM)
			&& now - resolvedTick >= RESULT_DISPLAY_TICKS)
		{
			status = Status.NONE;
		}
	}

	void onDeath(long tick)
	{
		if (lastPoisonHitTick >= 0)
		{
			long sinceHit = tick - lastPoisonHitTick;
			if (sinceHit <= 0 || sinceHit >= TIMER_TICKS)
			{
				// Killed by the timer's own hit, or the poison had worn off.
				clockMin = 0;
				clockMax = 0;
			}
			else
			{
				// It may count once more after the killing blow, like regen.
				clockMin = (int) sinceHit;
				clockMax = (int) Math.min(TIMER_TICKS - 1, sinceHit + 1);
			}
		}
		status = Status.NONE;
		lastPoisonHitTick = -1;
	}

	void cancel()
	{
		status = Status.NONE;
	}

	Status getStatus()
	{
		return status;
	}

	boolean isShared()
	{
		return shared;
	}

	long getAppliedTick()
	{
		return appliedTick;
	}

	long getProcEarliest()
	{
		return procEarliest;
	}

	long getProcLatest()
	{
		return procLatest;
	}

	long getFullHpTick()
	{
		return fullHpTick;
	}

	int getLastObservedDelay()
	{
		return lastObservedDelay;
	}

	/** @return fraction of the way from the venom hit to its latest first damage */
	double getProgress(long now)
	{
		long span = Math.max(1, procLatest - appliedTick);
		return Math.max(0, Math.min(1, (double) (now - appliedTick) / span));
	}

	/**
	 * The ticks in which to send dynamite that takes leadTicks to land so it
	 * lands at full health (regen runs before player hits in a tick) and before
	 * the earliest venom damage (which also runs first).
	 * @return {first, last} send tick, or null when not counting
	 */
	long[] getDynamiteWindow(int leadTicks)
	{
		if (status != Status.COUNTING)
		{
			return null;
		}
		long first = (fullHpTick >= 0 ? fullHpTick : appliedTick) - leadTicks;
		long last = procEarliest - 1 - leadTicks;
		return new long[]{first, last};
	}
}

package com.npchealthregen;

import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

final class NpcTimingProfileStore
{
	static final class Profile
	{
		private final int regenTicks;
		private final int respawnTicks;

		Profile(int regenTicks, int respawnTicks)
		{
			this.regenTicks = Math.max(0, regenTicks);
			this.respawnTicks = Math.max(0, respawnTicks);
		}

		int getRegenTicks()
		{
			return regenTicks;
		}

		int getRespawnTicks()
		{
			return respawnTicks;
		}
	}

	private static final String KEY_PREFIX = "learnedNpc_";
	// Kept separate from KEY_PREFIX so the existing "regen,respawn" format is unchanged.
	private static final String DEATH_PAUSE_KEY_PREFIX = "learnedDeathPause_";
	private final ConfigManager configManager;

	@Inject
	private NpcTimingProfileStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	Profile load(int npcId)
	{
		String stored = configManager.getConfiguration(
			NpcHealthRegenConfig.GROUP, KEY_PREFIX + npcId);
		return decode(stored);
	}

	void save(int npcId, int regenTicks, int respawnTicks)
	{
		configManager.setConfiguration(
			NpcHealthRegenConfig.GROUP,
			KEY_PREFIX + npcId,
			Math.max(0, regenTicks) + "," + Math.max(0, respawnTicks));
	}

	/** @return the learned {minimum, maximum} death-pause adjustment, or null if not learned */
	int[] loadDeathPause(int npcId)
	{
		return decodeDeathPause(configManager.getConfiguration(
			NpcHealthRegenConfig.GROUP, DEATH_PAUSE_KEY_PREFIX + npcId));
	}

	void saveDeathPause(int npcId, int minimum, int maximum)
	{
		configManager.setConfiguration(
			NpcHealthRegenConfig.GROUP,
			DEATH_PAUSE_KEY_PREFIX + npcId,
			minimum + "," + maximum);
	}

	static int[] decodeDeathPause(String stored)
	{
		if (stored == null || stored.isEmpty())
		{
			return null;
		}

		String[] parts = stored.split(",", -1);
		if (parts.length != 2)
		{
			return null;
		}

		try
		{
			int minimum = Integer.parseInt(parts[0]);
			int maximum = Integer.parseInt(parts[1]);
			return minimum <= maximum ? new int[]{minimum, maximum} : null;
		}
		catch (NumberFormatException ignored)
		{
			return null;
		}
	}

	static Profile decode(String stored)
	{
		if (stored == null || stored.isEmpty())
		{
			return new Profile(0, 0);
		}

		String[] parts = stored.split(",", -1);
		if (parts.length != 2)
		{
			return new Profile(0, 0);
		}

		try
		{
			return new Profile(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
		}
		catch (NumberFormatException ignored)
		{
			return new Profile(0, 0);
		}
	}
}
